// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "../.open-next/worker.js";
import { routeVoice } from "../src/lib/voice/server/route";

export { UserDO } from "./user-do";
export { CaseDO } from "./case-do";
export { VoiceDO } from "./voice-do";
export { PrepareFallback, LetterPipeline, NightlyWatch } from "./workflows";

type WorkflowBinding = { create(opts?: { id?: string; params?: unknown }): Promise<{ id: string }> };
type Bindings = { NIGHTLY_WATCH?: WorkflowBinding };

export default {
  /** Voice WebSockets (browser + Twilio) go straight to VoiceDO; everything else is the Next app. */
  async fetch(req: Request, env: Record<string, unknown>, ctx: unknown): Promise<Response> {
    const voice = await routeVoice(req, env as never);
    return voice ?? (openNext.fetch as (r: Request, e: unknown, c: unknown) => Promise<Response>)(req, env, ctx);
  },

  /** Cron `0 2 * * *` (02:00 UTC): start one NightlyWatch instance per day (id is duplicate-safe). */
  async scheduled(controller: { scheduledTime: number }, env: Bindings): Promise<void> {
    const day = new Date(controller.scheduledTime).toISOString().slice(0, 10);
    try {
      await env.NIGHTLY_WATCH?.create({ id: `nightly-${day}`, params: { day } });
    } catch {
      // An instance for this day already exists (cron fired twice); nothing to do.
    }
  },
};
